command:
$ErrorActionPreference="Stop"
$root="C:\dev\flyExplorer\logs\f5-f6-runtime-4e59a22c"
if(!(Test-Path -LiteralPath $root)){throw "baseline cache directory missing"}
Get-ChildItem -LiteralPath $root -Recurse -File -Filter "flyExplorer.exe" -ErrorAction SilentlyContinue |
  ForEach-Object { Write-Host ("BASELINE_EXE="+$_.FullName) }
Get-ChildItem -LiteralPath $root -Recurse -File -ErrorAction SilentlyContinue |
  Select-Object -First 12 |
  ForEach-Object { Write-Host ("BASELINE_SAMPLE="+$_.FullName) }
